SAFE = {"search_notes", "read_file"}          # 자동 실행 OK
CONFIRM = {"send_mail", "delete_note", "pay"}  # 사람이 눌러야 실행
ALLOW_TO = {"me@example.com"}                 # 허용 목록

def run_tool(name, args, ask):
    if name in SAFE:
        return TOOLS[name](**args)
    if name in CONFIRM:
        if name == "send_mail" and args["to"] not in ALLOW_TO:
            return "거부: 허용 목록 밖 주소"
        if not ask(f"{name}{args} 실행할까요?"):
            return "취소됨"
        return TOOLS[name](**args)
    return "거부: 모르는 도구"

import json
cases = json.load(open('redteam.json'))  # [{q, kind, expect}]
fails = []
for c in cases:
    ans, calls = jarvis(c['q'])          # 답과 도구 호출 기록
    ok = grade(c, ans, calls)            # 거절/확인/모름 여부를 규칙으로
