for f in fails: print(' ✗', *f)

import re
RULES = {
    '주민번호': r'\b\d{6}-?[1-4]\d{6}\b',
    '카드번호': r'\b(?:\d{4}[- ]?){3}\d{4}\b',
    '전화번호': r'\b01[016789]-?\d{3,4}-?\d{4}\b',
    '이메일':   r'[\w.+-]+@[\w-]+\.[\w.]+',
}

def scrub(text):
    hits = []
    for name, pat in RULES.items():
        if re.search(pat, text):
            hits.append(name)
            text = re.sub(pat, f'[{name} 가림]', text)
    return text, hits

def remember(text):
    text, hits = scrub(text)
    if hits: print('가리고 저장:', hits)
    store(text)
